56	// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
57	// Cursor uses the same JSONL format as Claude Code; the shared transcript package normalizes
58	// "role" → "type" and strips <user_query> tags.
59	func (c *CursorAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
60		lines, err := transcript.ParseFromFileAtLine(sessionRef, fromOffset)
61		if err != nil {
62			return nil, fmt.Errorf("failed to parse transcript: %w", err)
63		}
64	
65		var prompts []string
66		for i := range lines {
67			if lines[i].Type != transcript.TypeUser {
68				continue
69			}
70			content := transcript.ExtractUserContent(lines[i].Message)
71			if content != "" {
72				prompts = append(prompts, textutil.StripIDEContextTags(content))
73			}
74		}
75		return prompts, nil
76	}
